.mimir-xlsx-wrap { position: relative; background: var(--me-surface, #fff); }
.mimir-xlsx { border-collapse: collapse; table-layout: fixed; font-size: var(--me-font-size, 13px); font-variant-numeric: tabular-nums; }
.mimir-xlsx__gutter { position: sticky; left: 0px; z-index: 1; min-width: 34px; padding: 2px 6px; border: 1px solid var(--me-border, #d9d9d9); background-color: var(--me-surface, #fff); background-image: linear-gradient(var(--me-bar-bg, #fafafa), var(--me-bar-bg, #fafafa)); color: var(--me-text-weak, #8c8c8c); font-weight: normal; text-align: center; user-select: none; }
.mimir-xlsx__colhead { position: sticky; top: 0px; z-index: 1; min-width: 34px; padding: 2px 6px; border: 1px solid var(--me-border, #d9d9d9); background-color: var(--me-surface, #fff); background-image: linear-gradient(var(--me-bar-bg, #fafafa), var(--me-bar-bg, #fafafa)); color: var(--me-text-weak, #8c8c8c); font-weight: normal; text-align: center; user-select: none; }
.mimir-xlsx__corner { z-index: 2; }
.mimir-xlsx__cell { padding: 2px 6px; border: 1px solid var(--me-border, #d9d9d9); background: var(--me-surface, #fff); color: var(--me-text, #262626); vertical-align: top; white-space: nowrap; overflow-wrap: normal; overflow: hidden; text-overflow: ellipsis; cursor: cell; }
.mimir-xlsx__cell:hover { background: var(--me-hover, #f0f0f0); }
